import unittest
from slugger import slugify

class SlugTests(unittest.TestCase):
    def test_words(self):
        self.assertEqual(slugify('  Hello Flow  '), 'hello-flow')

    def test_already_slugged(self):
        self.assertEqual(slugify('Ego-Agent'), 'ego-agent')
